package service;import java.util.concurrent.*;public class TransactionProcessor implements AutoCloseable{private final ExecutorService pool=Executors.newFixedThreadPool(4);public void submit(Runnable r){pool.execute(r);}public void stop(){pool.shutdown();try{if(!pool.awaitTermination(10,TimeUnit.SECONDS))pool.shutdownNow();}catch(InterruptedException e){pool.shutdownNow();Thread.currentThread().interrupt();}}public void close(){stop();}}
